def asset_img(name,alt='',classes='',eager=False,sizes='(max-width: 700px) 100vw, 50vw'):
 if '.' in name:
  p=ASSETS/name
  if p.suffix=='.svg':w=h=2000
  else:
   with Image.open(p) as im:w,h=im.size
  src='/assets/'+name;srcset=''
 else:
  options=sorted(ASSETS.glob(name+'-*.webp'),key=lambda p:int(p.stem.rsplit('-',1)[1]));p=options[-1]
  with Image.open(p) as im:w,h=im.size
  src='/assets/'+p.name;srcset=' srcset="'+', '.join('/assets/'+a.name+' '+a.stem.rsplit('-',1)[1]+'w' for a in options)+'" sizes="'+sizes+'"'
 return f'<img src="{src}"{srcset} width="{w}" height="{h}" alt="{esc(alt)}" class="{classes}" loading="{"eager" if eager else "lazy"}" decoding="async">'
